"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import {
  ArrowRight,
  Sparkles,
  ShieldCheck,
  Users,
  Star,
} from "lucide-react";
import { HeroBanner } from "@/components/customer/HeroBanner";
import ServiceCard  from "@/components/customer/ServiceCard";
import { ProductCard } from "@/components/customer/ProductCard";
import { Testimonials } from "@/components/customer/Testimonials";
import { PromoCarousel } from "@/components/customer/PromoCarousel";
import { PosterSection } from "@/components/customer/PosterSection";
import { apiClient } from "@/api/client";
import { Service } from "@/types/service";
import { Product } from "@/types/product";

export default function HomePage() {
  const router = useRouter();
  // Initialize with empty arrays to prevent 'undefined' errors
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [servicesRes, productsRes] = await Promise.all([
          apiClient.get("/services?limit=4&featured=true"),
          apiClient.get("/products?limit=4&popular=true"),
        ]);

        // SAFELY extract data. If path doesn't exist, default to empty array.
        // API Shape: { success: true, data: { data: [...], total: 0 } }
        const servicesData = servicesRes.data?.data?.data;
        const productsData = productsRes.data?.data?.data;

        setServices(Array.isArray(servicesData) ? servicesData : []);
        setProducts(Array.isArray(productsData) ? productsData : []);
      } catch (error) {
        console.error("Failed to fetch home data:", error);
        setServices([]);
        setProducts([]);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Defensive slicing: Ensure it's an array before slicing
  const featuredServices = (Array.isArray(services) ? services : []).slice(0, 4);
  const popularProducts = (Array.isArray(products) ? products : []).slice(0, 4);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
      </div>
    );
  }

  return (
    <main className="min-h-screen flex flex-col">
      {/* 1. Hero Section */}
      <HeroBanner />

      {/* 2. Promo / Offers Section */}
      <section className="w-full bg-slate-50 py-16">
        <div className="container mx-auto px-4">
          <div className="mb-8">
            <h2 className="text-2xl font-bold tracking-tight text-slate-900 md:text-3xl">
              Exclusive Offers
            </h2>
            <p className="mt-2 text-slate-600">
              Limited time deals for premium car care
            </p>
          </div>
          <PromoCarousel />
        </div>
      </section>

      {/* 3. Services Section */}
      <section className="w-full bg-white py-20 border-y border-slate-100">
        <div className="container mx-auto px-4">
          <div className="mb-12 md:flex md:items-end md:justify-between">
            <div className="max-w-2xl">
              <div className="flex items-center gap-2 text-sky-600 mb-3">
                <Sparkles className="h-5 w-5" />
                <span className="font-bold uppercase tracking-wider text-sm">
                  Our Services
                </span>
              </div>
              <h2 className="text-3xl font-extrabold tracking-tight text-slate-900 sm:text-4xl">
                Professional Car Care
              </h2>
              <p className="mt-4 text-lg text-slate-600 leading-relaxed">
                Experience the finest detailing and wash services, delivered
                with precision and care.
              </p>
            </div>
            <div className="mt-6 md:mt-0">
              <Button
                onClick={() => router.push("/services")}
                className="bg-sky-500 hover:bg-sky-600 text-white px-6"
              >
                View All Services <ArrowRight className="ml-2 h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* SAFE CHECK: Use optional chaining for length */}
          {featuredServices && featuredServices.length > 0 ? (
            <div className="grid gap-8 sm:grid-cols-2 lg:grid-cols-4">
              {featuredServices.map((service) => (
                <ServiceCard key={service._id} service={service} />
              ))}
            </div>
          ) : (
            <p className="text-center text-slate-500 py-12">
              No featured services available at the moment.
            </p>
          )}
        </div>
      </section>

      {/* 4. Poster Section */}
      <PosterSection />

      {/* 5. Products Section */}
      <section className="w-full bg-slate-50 py-20">
        <div className="container mx-auto px-4">
          <div className="mb-10 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h2 className="text-3xl font-bold text-slate-900">
                Popular Products
              </h2>
              <p className="text-slate-600 mt-2">
                Professional grade car care for your home garage
              </p>
            </div>
            <Button
              variant="outline"
              onClick={() => router.push("/products")}
              className="border-slate-300 text-slate-700 hover:bg-white"
            >
              Shop All Products
            </Button>
          </div>

          {/* SAFE CHECK: Use optional chaining for length */}
          {popularProducts && popularProducts.length > 0 ? (
            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
              {popularProducts.map((product) => (
                <ProductCard key={product._id} product={product} />
              ))}
            </div>
          ) : (
            <p className="text-center text-slate-500 py-12">
              No products available at the moment.
            </p>
          )}
        </div>
      </section>

      {/* 6. Stats / Trust Section */}
      <section className="w-full bg-white py-16 border-t border-slate-100">
        <div className="container mx-auto px-4">
          <div className="grid gap-8 sm:grid-cols-3 text-center">
            <div className="flex flex-col items-center p-6 rounded-2xl bg-slate-50 hover:bg-white hover:shadow-lg transition-all duration-300 border border-transparent hover:border-slate-100">
              <div className="p-4 rounded-full bg-sky-100 text-sky-600 mb-4">
                <Users className="h-8 w-8" />
              </div>
              <h3 className="text-4xl font-bold text-slate-900">5000+</h3>
              <p className="text-slate-600 font-medium mt-2">
                Happy Customers
              </p>
            </div>
            <div className="flex flex-col items-center p-6 rounded-2xl bg-slate-50 hover:bg-white hover:shadow-lg transition-all duration-300 border border-transparent hover:border-slate-100">
              <div className="p-4 rounded-full bg-sky-100 text-sky-600 mb-4">
                <ShieldCheck className="h-8 w-8" />
              </div>
              <h3 className="text-4xl font-bold text-slate-900">50+</h3>
              <p className="text-slate-600 font-medium mt-2">Expert Staff</p>
            </div>
            <div className="flex flex-col items-center p-6 rounded-2xl bg-slate-50 hover:bg-white hover:shadow-lg transition-all duration-300 border border-transparent hover:border-slate-100">
              <div className="p-4 rounded-full bg-sky-100 text-sky-600 mb-4">
                <Star className="h-8 w-8" />
              </div>
              <h3 className="text-4xl font-bold text-slate-900">4.9</h3>
              <p className="text-slate-600 font-medium mt-2">
                Average Rating
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* 7. Testimonials Section */}
      <section className="w-full bg-[#0f172a] py-20 text-white">
        <div className="container mx-auto px-4">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-white sm:text-4xl">
              What Our Customers Say
            </h2>
            <p className="text-slate-400 mt-3 text-lg">
              Don&apos;t just take our word for it
            </p>
          </div>
          <Testimonials />
        </div>
      </section>
    </main>
  );
}
